"It's Saturday morning.":"Šeštadienio rytas.",
"I want to bake a cake for Mum!":"Noriu iškepti pyragą mamai!",
"Can I help you?":"Ar galiu tau padėti?",
"Yes! We need flour, eggs and sugar.":"Taip! Mums reikia miltų, kiaušinių ir cukraus.",
"Meow!":"Miau!",
"Pus, don't eat the butter!":"Pusai, nevalgyk sviesto!",
"Oh no! Flour all over the kitchen!":"O ne! Miltai po visą virtuvę!",
"The cake is ready. It's a bit crooked...":"Pyragas gatavas. Truputį kreivas…",
"But it smells so good!":"Bet kaip skaniai kvepia!",
"Thank you so much, my darlings! This is the best cake in the world!":"Labai ačiū, mano brangieji! Tai geriausias pyragas pasaulyje!",
"Meow, meow!":"Miau, miau!",
"Good morning, Leo! Today is your first day at school.":"Labas rytas, Leo! Šiandien tavo pirmoji diena mokykloje.",
"I'm a little scared, Mum.":"Man truputį baisu, mama.",
"Hi and welcome! My name is Ingrid. What's your name?":"Labas, sveikas atvykęs! Aš Ingrid. O kuo tu vardu?",
"My name is Leo. I come from Ukraine.":"Mano vardas Leo. Aš iš Ukrainos.",
"Hi, Leo! Do you want to sit next to me?":"Labas, Leo! Nori sėdėti šalia manęs?",
"Yes, I'd love to!":"Taip, labai noriu!",
"What is one plus two?":"Kiek yra vienas plius du?",
"Three!":"Trys!",
"You're so clever!":"Koks tu protingas!",
"Break time!":"Pertrauka!",
"Come on, let's play football!":"Eime, pažaiskime futbolą!",
"How was school?":"Kaip sekėsi mokykloje?",
"Super fun! Nora is my new friend!":"Labai smagu! Nora — mano nauja draugė!",
"Today we're going for a walk in the forest!":"Šiandien einame pasivaikščioti į mišką!",
"Hooray! I'll bring the basket.":"Valio! Aš pasiimsiu krepšį.",
"Look, there's a mushroom!":"Žiūrėk, ten grybas!",
"That mushroom is poisonous. Don't eat it!":"Tas grybas nuodingas. Nevalgyk jo!",
"There are lots of blueberries here!":"Čia daugybė mėlynių!",
"Yum! They're so sweet!":"Skanu! Tokios saldžios!",
"What was that?":"Kas tai buvo?",
"A moose! It's huge!":"Briedis! Jis milžiniškas!",
"Then it starts to rain.":"Tada pradeda lyti.",
"Be quiet. Now we walk home calmly.":"Tylėk. Dabar ramiai einame namo.",
"Now we're going to drink hot cocoa.":"Dabar gersime karštą kakavą.",
"That was a lovely walk!":"Koks puikus pasivaikščiojimas!",
"And we saw a real moose!":"Ir pamatėme tikrą briedį!",
"Mia, can you do the shopping for me?":"Mija, ar gali man nupirkti maisto?",
"Yes! What do you need?":"Taip! Ko reikia?",
"We need milk, bread and apples. Here are a hundred kroner.":"Reikia pieno, duonos ir obuolių. Štai šimtas kronų.",
"Thanks, Mum!":"Ačiū, mama!",
"Excuse me, where is the milk?":"Atsiprašau, kur yra pienas?",
"The milk is over there, by the bread.":"Pienas ten, prie duonos.",
"I'll take six red apples.":"Imsiu šešis raudonus obuolius.",
"That will be eighty kroner.":"Bus aštuoniasdešimt kronų.",
"Here you go, here's a hundred.":"Prašom, štai šimtas.",
"Twenty kroner change. Have a nice day!":"Dvidešimt kronų grąžos. Geros dienos!",
"You're so clever, Mia! Thank you so much.":"Kokia tu protinga, Mija! Labai ačiū.",
"That was easy!":"Buvo lengva!",
"Meow! Milk?":"Miau! Pieno?",
