"The passive":"Pasyvas",
"The passive shows that something is done to the subject. Bli + participle for a specific event: “Huset ble bygd i 1990”. The s-passive for rules and regular actions: “Butikken åpnes klokka ni”, “Det snakkes norsk her”. After modals: “Søknaden må sendes i dag”.":"Pasyvas rodo, kad veiksmas atliekamas subjektui. Bli + dalyvis konkrečiam įvykiui: „Huset ble bygd i 1990”. s-pasyvas taisyklėms ir įprastiems veiksmams: „Butikken åpnes klokka ni”, „Det snakkes norsk her”. Po modalinių veiksmažodžių: „Søknaden må sendes i dag”.",
"The house was built in 1990.":"Namas buvo pastatytas 1990 m.",
"The shop opens at nine.":"Parduotuvė atidaroma devintą valandą.",
"The application must be sent today.":"Paraiška turi būti išsiųsta šiandien.",
"The book was written by Ibsen.":"Knygą parašė Ibsenas.",
"Many languages are spoken in Oslo.":"Osle kalbama daug kalbų.",
"The position was advertised in March.":"Pareigos buvo paskelbtos kovo mėnesį.",
"Formal linking words":"Formalūs jungiamieji žodžiai",
"For essays, letters and debates: derfor (therefore), likevel (nevertheless), dessuten (moreover), ettersom (since), selv om (although), i motsetning til (unlike), på grunn av (because of) + noun, for å (in order to) + infinitive. Derfor/likevel/dessuten at the start trigger inversion: “Derfor må vi…”.":"Rašiniuose, laiškuose ir debatų tekstuose: derfor (todėl), likevel (vis dėlto), dessuten (be to), ettersom (kadangi), selv om (nors), i motsetning til (priešingai nei), på grunn av (dėl) + daiktavardis, for å (tam, kad) + bendratis. Žodžiai derfor/likevel/dessuten sakinio pradžioje sukelia inversiją: „Derfor må vi…“.",
"moreover":"be to",
"since, as":"kadangi",
"because of":"dėl",
"in order to":"tam, kad",
"unlike":"priešingai nei",
"It was raining. Nevertheless we went hiking.":"Lijo. Vis dėlto ėjome į žygį.",
"The train was delayed because of the snow.":"Traukinys vėlavo dėl sniego.",
