"A Rainy Day in London":"Lietinga diena Londone",
"Oh no, it is raining again!":"O ne, vėl lyja!",
"Welcome to London. Did you bring an umbrella?":"Sveiki atvykę į Londoną. Ar pasiėmėte skėtį?",
