"We cannot walk in the park today.":"Šiandien negalime vaikščioti parke.",
"Let us take the bus to the museum instead.":"Vietoj to važiuokime į muziejų autobusu.",
"Great idea! Which bus goes there?":"Puiki mintis! Koks autobusas ten važiuoja?",
