"Perfect. The museum is free on Sundays.":"Puiku. Muziejus sekmadieniais nemokamas.",
"Look at this old map of the city!":"Pažiūrėk į šį seną miesto žemėlapį!",
"I love rainy days when we find something new.":"Man patinka lietingos dienos, kai randame ką nors naujo.",
