"Lost in the City":"Pasiklydęs mieste",
"Excuse me, could you help me? I think I am lost.":"Atsiprašau, ar galite man padėti? Man atrodo, kad pasiklydau.",
"Of course. Where do you want to go?":"Žinoma. Kur norite nuvykti?",
"I am looking for the city library.":"Ieškau miesto bibliotekos.",
"Go straight on and turn left at the traffic lights.":"Eikite tiesiai ir prie šviesoforo pasukite kairėn.",
"Then walk past the bus stop. The library is opposite the bank.":"Tada praeikite autobusų stotelę. Biblioteka yra priešais banką.",
"Is it far from here?":"Ar toli nuo čia?",
"No, it only takes about ten minutes on foot.":"Ne, pėsčiomis užtruksite tik apie dešimt minučių.",
"Great. And is there a café near the library?":"Puiku. O ar netoli bibliotekos yra kavinė?",
"Later, Ruslan took the wrong bus.":"Vėliau Ruslanas įsėdo į ne tą autobusą.",
"This bus does not go there. Get off at the next stop and cross the road.":"Šis autobusas ten nevažiuoja. Išlipk kitoje stotelėje ir pereik gatvę.",
"Finally! The library is on the corner, just like you said.":"Pagaliau! Biblioteka yra kampe, kaip ir sakei.",
"Well done! Now you will never get lost again.":"Šaunu! Dabar daugiau niekada nepasiklysi.",
