"Grammar in real life":"Gramatika realiame gyvenime (aiškinimas apie norvegišką raidę, garsą ar skaičių besimokančiajam)",
"What is coding?":"Kas yra programavimas?",
"The school has a robot called Robo. He only follows exact commands, and the children learn that a program is commands in the right order.":"Mokykla turi robotą Robo. Jis vykdo tik tikslias komandas, o vaikai sužino, kad programa – tai komandos teisinga tvarka.",
"Look, Nora! The school has got a robot.":"Žiūrėk, Nora! Mokykla gavo robotą.",
"Hi, robot! What is your name?":"Labas, robote! Kuo tu vardu?",
"Hi! My name is Robo. I do what you tell me.":"Labas! Mano vardas Robo. Darau tai, ką man liepiate.",
"Robo only understands commands. We call that programming.":"Robo supranta tik komandas. Tai vadiname programavimu.",
"What is a command?":"Kas yra komanda?",
"A command is a short instruction, for example “walk” or “turn”.":"Komanda – tai trumpas nurodymas, pavyzdžiui, „eik“ arba „pasisuk“.",
"Robo, take two steps forward!":"Robo, žengk du žingsnius į priekį!",
"Walking. One, two. Done!":"Einu. Vienas, du. Baigta!",
"Robo, make me a pizza!":"Robo, padaryk man picą!",
"Error! I do not know the command “pizza”.":"Klaida! Nežinau komandos „pica“.",
"A program is many commands in the right order.":"Programa – tai daug komandų teisinga tvarka.",
"So we have to think step by step!":"Vadinasi, turime galvoti žingsnis po žingsnio!",
"I want to learn to code!":"Noriu išmokti programuoti!",
"And I want to learn to make pizza.":"O aš noriu išmokti kepti picą.",
"a robot":"robotas",
