"to turn":"pasisukti",
"done, finished":"baigta",
"error; wrong":"klaida; neteisingai",
"to know":"žinoti",
"an order, a sequence":"tvarka, seka",
"right, correct":"teisingas",
"step by step":"žingsnis po žingsnio",
"The sandwich algorithm":"Sumuštinio algoritmas",
"Leo teaches Robo the robot to make a sandwich. Robo does everything literally, so Leo learns that an algorithm must be exact and in the right order.":"Leo moko robotą Robo pasigaminti sumuštinį. Robo viską daro pažodžiui, todėl Leo sužino, kad algoritmas turi būti tikslus ir teisinga tvarka.",
"Dad, I am going to teach Robo to make a sandwich.":"Tėti, išmokysiu Robo pasigaminti sumuštinį.",
"Then you need an algorithm.":"Tada tau reikia algoritmo.",
"What is an algorithm?":"Kas yra algoritmas?",
"An algorithm is like a recipe: step by step, in the right order.":"Algoritmas – kaip receptas: žingsnis po žingsnio, teisinga tvarka.",
"Step one: Take the bread. Step two: Put on butter.":"Pirmas žingsnis: paimk duoną. Antras žingsnis: patepk sviestu.",
"Butter on … the table? Done!":"Sviestas ant… stalo? Atlikta!",
"Ha ha! You have to say exactly what Robo should do.":"Cha cha! Turi tiksliai pasakyti, ką Robo turi daryti.",
"New step two: Put butter on the slice of bread!":"Naujas antras žingsnis: patepk duonos riekę sviestu!",
"Step three: Put on cheese. Step four: Give the sandwich to Leo.":"Trečias žingsnis: uždėk sūrio. Ketvirtas žingsnis: duok sumuštinį Leo.",
"Done! Here you are.":"Atlikta! Prašom.",
"Mmm! The algorithm works!":"Mmm! Algoritmas veikia!",
"And remember: the order is important. First butter, then cheese.":"Ir atsimink: tvarka svarbi. Pirma sviestas, paskui sūris.",
"an algorithm":"algoritmas",
"a slice of bread, a sandwich":"duonos riekė, sumuštinis",
"a cheese":"sūris",
"to put on":"uždėti",
"done, carried out":"atlikta",
"important":"svarbus",
"then":"paskui",
"Repeat! Robo dances":"Kartok! Robo šoka",
"Nora wants Robo to dance, but there are too many commands. The teacher shows a loop: “repeat 4 times” — and the program becomes short.":"Nora nori, kad Robo šoktų, bet komandų per daug. Mokytoja parodo ciklą: „kartok 4 kartus“ – ir programa tampa trumpa.",
"Robo, jump! Clap! Jump! Clap! Jump! Clap!":"Robo, šok! Suplok! Šok! Suplok! Šok! Suplok!",
"Jump. Clap. Jump. Clap …":"Šuolis. Pliaukš. Šuolis. Pliaukš…",
"Phew, that is a lot to write.":"Uf, tiek daug rašyti.",
"Use a loop! A loop repeats commands.":"Naudok ciklą! Ciklas kartoja komandas.",
"Write: repeat four times: jump and clap.":"Rašyk: kartok keturis kartus: šuolis ir pliaukštelėjimas.",
"So short!":"Kaip trumpai!",
"Jump, clap! Jump, clap! Jump, clap! Jump, clap!":"Šuolis, pliaukš! Šuolis, pliaukš! Šuolis, pliaukš! Šuolis, pliaukš!",
"Robo is dancing!":"Robo šoka!",
"Can we repeat it a hundred times?":"Ar galime pakartoti šimtą kartų?",
"Yes. Computers never get tired.":"Taip. Kompiuteriai niekada nepavargsta.",
"But Robo is getting dizzy …":"Bet Robo apsvaigsta…",
"Ha ha! We are stopping the loop now.":"Cha cha! Dabar sustabdome ciklą.",
"a loop":"ciklas",
"to jump":"šokinėti",
"to clap":"ploti",
"a lot":"daug",
"to use":"naudoti",
"four times":"keturis kartus",
"a hundred":"šimtas",
"to stop":"sustabdyti",
"If it rains …":"Jei lyja…",
"Robo does not know when to take an umbrella. Leo and Mum write him a rule: if it rains — an umbrella, otherwise — sunglasses.":"Robo nežino, kada pasiimti skėtį. Leo ir mama parašo jam taisyklę: jei lyja – skėtis, kitaip – akiniai nuo saulės.",
"Robo, we are going out. Bring an umbrella.":"Robo, einame į lauką. Pasiimk skėtį.",
"Why? The sun is shining.":"Kodėl? Šviečia saulė.",
"You are right, Robo. We need a rule.":"Tu teisus, Robo. Mums reikia taisyklės.",
"If it rains, we take an umbrella.":"Jei lyja, imame skėtį.",
"If it rains, then we take an umbrella. Otherwise we take sunglasses.":"Jei lyja, tada imame skėtį. Kitaip imame akinius nuo saulės.",
"If … then … otherwise. Understood!":"Jei… tai… kitaip. Supratau!",
"It is raining. I am taking the umbrella.":"Lyja. Imu skėtį.",
"Good, Robo!":"Šaunu, Robo!",
"Now the sun is shining. I am taking sunglasses.":"Dabar šviečia saulė. Imu akinius nuo saulės.",
"Robo thinks like a computer.":"Robo galvoja kaip kompiuteris.",
"If I tidy my room, then I get ice cream?":"Jei susitvarkysiu kambarį, gausiu ledų?",
"Yes! That is a good rule.":"Taip! Tai gera taisyklė.",
"otherwise, else":"kitaip",
"an umbrella":"skėtis",
