"Points in the box":"Taškai dėžutėje",
"Nora and Leo make a game: a cat catches fish and gets points. The teacher explains a variable — a box with a name where the computer keeps a number.":"Nora ir Leo kuria žaidimą: katė gaudo žuvis ir gauna taškų. Mokytoja paaiškina kintamąjį – dėžutę su pavadinimu, kurioje kompiuteris laiko skaičių.",
"We are making a game! Every time the cat catches a fish, we get a point.":"Kuriame žaidimą! Kiekvieną kartą, kai katė pagauna žuvį, gauname tašką.",
"But where will the computer remember the points?":"Bet kur kompiuteris atsimins taškus?",
"In a variable. A variable is like a box with a name.":"Kintamajame. Kintamasis – kaip dėžutė su pavadinimu.",
"The box is called “points”. Right now there is zero in the box.":"Dėžutė vadinasi „taškai“. Dabar joje nulis.",
"The cat catches a fish!":"Katė pagauna žuvį!",
"Then we write: points equals points plus one.":"Tada rašome: taškai lygu taškai plius vienas.",
"Points is one. Points is two. Points is three!":"Taškai – vienas. Taškai – du. Taškai – trys!",
"The value in the box changes!":"Reikšmė dėžutėje keičiasi!",
"Can we have more boxes?":"Ar galime turėti daugiau dėžučių?",
"Yes. Name, lives and speed … A game has many variables.":"Taip. Vardas, gyvybės ir greitis… Žaidimas turi daug kintamųjų.",
"We have ten points! We won!":"Turime dešimt taškų! Laimėjome!",
"The variable “joy” is now a hundred.":"Kintamasis „džiaugsmas“ dabar lygus šimtui.",
