"Find the bug!":"Rask klaidą!",
"Robo has to reach the star but walks into a wall. The children read the program line by line, find the bug and fix it.":"Robo turi nueiti iki žvaigždės, bet atsitrenkia į sieną. Vaikai skaito programą eilutė po eilutės, randa klaidą ir ją ištaiso.",
"Robo has to walk to the star. I have written the program.":"Robo turi nueiti iki žvaigždės. Parašiau programą.",
"I am starting the program now.":"Dabar paleidžiu programą.",
"Ouch! I walked straight into the wall.":"Ai! Nuėjau tiesiai į sieną.",
"Oops! The program has a bug.":"Oi! Programoje yra klaida.",
"We call an error in a program a bug.":"Programos klaidą vadiname bugu.",
"Finding and fixing the error is called debugging.":"Klaidos paieška ir taisymas vadinamas derinimu.",
"We read the program line by line: forward, forward, right …":"Skaitome programą eilutė po eilutės: pirmyn, pirmyn, dešinėn…",
"There! It should say left, not right.":"Štai! Turi būti kairėn, ne dešinėn.",
"Now I will fix the bug and try again.":"Dabar ištaisysiu klaidą ir bandysiu dar kartą.",
"I am at the star! The program works.":"Aš prie žvaigždės! Programa veikia.",
"All programmers make mistakes. The important thing is to try again.":"Visi programuotojai klysta. Svarbiausia – bandyti dar kartą.",
"Mistakes are part of learning!":"Klaidos yra mokymosi dalis!",
