"Which language?":"Kuri kalba?",
"Leo asks Robo which language he speaks. The teacher explains programming languages: Scratch, Python, JavaScript, HTML and CSS, Swift, Kotlin and C#.":"Leo klausia Robo, kokia kalba jis kalba. Mokytoja paaiškina programavimo kalbas: Scratch, Python, JavaScript, HTML ir CSS, Swift, Kotlin ir C#.",
"Robo, which language do you speak? Norwegian?":"Robo, kokia kalba kalbi? Norvegiškai?",
"I understand programming languages. There are many!":"Suprantu programavimo kalbas. Jų yra daug!",
"Children often start with Scratch. There we move colourful blocks.":"Vaikai dažnai pradeda nuo Scratch. Ten stumdome spalvotus blokus.",
"It looks like Lego!":"Atrodo kaip Lego!",
"Python is easy to read. It is used for games, data and artificial intelligence.":"Python lengva skaityti. Jis naudojamas žaidimams, duomenims ir dirbtiniam intelektui.",
"Artificial intelligence? Like Robo?":"Dirbtinis intelektas? Kaip Robo?",
"HTML builds web pages, and CSS makes them pretty. JavaScript makes them move.":"HTML kuria tinklalapius, o CSS juos padaro gražius. JavaScript juos pajudina.",
"So the school website is made with them?":"Vadinasi, mokyklos svetainė padaryta su jomis?",
"We make iPhone apps with Swift, and Android apps with Kotlin.":"iPhone programėles kuriame su Swift, o Android – su Kotlin.",
"And games?":"O žaidimai?",
"Many games are made with C#.":"Daug žaidimų kuriama su C#.",
"Which language should I learn first?":"Kurią kalbą man mokytis pirmiausia?",
"Start with Scratch or Python. The most important thing is to think logically.":"Pradėk nuo Scratch arba Python. Svarbiausia – mąstyti logiškai.",
