"A model of the school":"Mokyklos modelis",
"The class makes a model of the schoolyard. The children learn that a model is a simple copy, that things in a program have properties, and that you draw the plan before the code.":"Klasė kuria mokyklos kiemo modelį. Vaikai sužino, kad modelis – paprasta kopija, kad daiktai programoje turi savybių ir kad planą piešiame prieš kodą.",
"Today we are making a model of the schoolyard.":"Šiandien kuriame mokyklos kiemo modelį.",
"What is a model?":"Kas yra modelis?",
"A model is a simple copy of something real. A map is a model too.":"Modelis – tai paprasta kažko tikro kopija. Žemėlapis irgi yra modelis.",
"Like the map in a game!":"Kaip žemėlapis žaidime!",
"We only draw the important things: the school, the gate and the football pitch.":"Piešiame tik tai, kas svarbu: mokyklą, vartus ir futbolo aikštę.",
"We do not need to draw every single leaf.":"Nereikia piešti kiekvieno lapelio.",
"In a program we describe things with properties. A ball has a colour, a size and a speed.":"Programoje daiktus aprašome savybėmis. Kamuolys turi spalvą, dydį ir greitį.",
"So the ball is white and fast!":"Vadinasi, kamuolys baltas ir greitas!",
"And a flowchart shows what happens, step by step.":"O blokinė schema rodo, kas vyksta, žingsnis po žingsnio.",
"First we draw the plan, then we write the code.":"Pirmiausia piešiame planą, paskui rašome kodą.",
"I have made a model of Leo: hungry, happy and likes football.":"Padariau Leo modelį: alkanas, linksmas ir mėgsta futbolą.",
"Ha ha! That is right!":"Cha cha! Tiesa!",
