"A website for Pus: HTML basics":"Svetainė Pusui: HTML pagrindai",
"Nora and Leo make a website about Pus the cat. Robo explains HTML: tags in angle brackets, a heading <h1>, a paragraph <p>, an image <img> and a link <a>.":"Nora ir Leo kuria svetainę apie katiną Pusą. Robo paaiškina HTML: žymes kampiniuose skliaustuose, antraštę <h1>, pastraipą <p>, paveikslėlį <img> ir nuorodą <a>.",
"I want to make a website about our cat, Pus!":"Noriu sukurti svetainę apie mūsų katiną Pusą!",
"Then we need HTML.":"Tada mums reikia HTML.",
"HTML builds web pages. It is made of tags.":"HTML kuria tinklalapius. Jis sudarytas iš žymių.",
"What is a tag?":"Kas yra žymė?",
"A tag is a short word in angle brackets, for example p.":"Žymė – tai trumpas žodis kampiniuose skliaustuose, pavyzdžiui, p.",
"Most tags have a start and an end. The end tag has a slash.":"Dauguma žymių turi pradžią ir pabaigą. Uždaromoji žymė turi pasvirąjį brūkšnį.",
"Like a sandwich!":"Kaip sumuštinis!",
"I write h1 and “Pus”. It becomes a big heading!":"Rašau h1 ir „Pus“. Gaunasi didelė antraštė!",
"Yes. h1 means heading number one.":"Taip. h1 reiškia pirmo lygio antraštę.",
"With p we make a paragraph, and with img we show a picture.":"Su p kuriame pastraipą, o su img rodome paveikslėlį.",
"Look, a picture of Pus!":"Žiūrėk, Puso nuotrauka!",
"Finally a link. The a tag takes us to another page.":"Galiausiai nuoroda. Žymė a nuveda į kitą puslapį.",
"The website is ready! Next time we will make it pretty with CSS.":"Svetainė paruošta! Kitą kartą ją pagražinsime su CSS.",
